// "refactored" pricing — every function is now tiny
 function priceFor(item: Item): number {
   return roundMoney(applyTax(applyDiscount(baseCost(item))));
 }
+function baseCost(i: Item): number { return i.qty * i.unit; }
+function applyDiscount(x: number): number { return x * 0.9; }
+function applyTax(x: number): number { return x * 1.2; }
+function roundMoney(x: number): number { return Math.round(x * 100) / 100; }
+function isLineEmpty(i: Item): boolean { return i.qty === 0; }
